package com.amicbeam.beyondcraftlines.common.network;
import com.amicbeam.beyondcraftlines.BeyondCraftlines;import com.amicbeam.beyondcraftlines.common.data.DeviceBindingRegistry;import com.amicbeam.beyondcraftlines.common.menu.*;import com.amicbeam.beyondcraftlines.common.runtime.CraftlineDashboardBlockEntity;import com.wintercogs.beyonddimensions.api.storage.key.IStackKey;import io.netty.buffer.ByteBuf;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.SimpleMenuProvider;import net.neoforged.neoforge.network.handling.IPayloadContext;import org.jetbrains.annotations.NotNull;
public record OpenDashboardRecipePayload(BlockPos position)implements CustomPacketPayload{public static final Type<OpenDashboardRecipePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(BeyondCraftlines.MOD_ID,"open_dashboard_recipe"));public static final StreamCodec<ByteBuf,OpenDashboardRecipePayload> STREAM_CODEC=StreamCodec.composite(BlockPos.STREAM_CODEC,OpenDashboardRecipePayload::position,OpenDashboardRecipePayload::new);public static void handle(OpenDashboardRecipePayload p,IPayloadContext c){c.enqueueWork(()->{if(!(c.player() instanceof ServerPlayer player)||!(player.containerMenu instanceof DashboardConfigMenu menu)||!menu.position().equals(p.position())||!(player.level().getBlockEntity(p.position()) instanceof CraftlineDashboardBlockEntity d)||!d.mayConfigure(player)||d.target().isEmpty())return;int networkId=d.getNetId();var families=DeviceBindingRegistry.availableFamilies(player.level().getServer(),networkId);player.openMenu(new SimpleMenuProvider((id,inv,x)->new CraftlineOrderMenu(id,inv,networkId,d.target(),null,false,families,p.position(),d.recipe().blockingMode(),d.desiredAmount(),d.stockMode().id()),Component.translatable("menu.beyond_craftlines.dashboard_recipe")),buffer->{buffer.writeVarInt(networkId);IStackKey.STREAM_CODEC.encode(buffer,d.target());buffer.writeUtf("");buffer.writeBoolean(false);buffer.writeVarInt(families.size());families.stream().sorted().forEach(buffer::writeUtf);buffer.writeBoolean(true);buffer.writeBlockPos(p.position());buffer.writeBoolean(d.recipe().blockingMode());buffer.writeVarLong(d.desiredAmount());buffer.writeUtf(d.stockMode().id(),16);});});}@Override public @NotNull Type<? extends CustomPacketPayload> type(){return TYPE;}}
